package main

import (
    "crypto/sha256"
    "encoding/base64"
)

func hashExample(password string) (string, string, error) {
    // Generate a random salt of length equal to SHA256 output (32 bytes)
    salt := make([]byte, sha256.New().Size())

    if _, err := rand.Read(salt); err != nil {
        return "", "", err
    }

    // Create PBKDF2-HMAC with SHA256, 10,000 iterations
    key := pbkdf2.Key(password, salt, 10000, sha256.New().Size(), hmac.New(sha256.New, []byte(password)))

    // Encode the salt and hashed password in base64 for storage
    saltStr := base64.StdEncoding.EncodeToString(salt)
    hashStr := base64.StdEncoding.EncodeToString(key)

    return saltStr, hashStr, nil
}

go
package main

import (
    "crypto/sha256"
    "crypto/hmac"
    "encoding/base64"
)

func examplePBKDF2(password string, salt []byte) (string, string, error) {
    // Generate a random salt of length equal to SHA256 output (32 bytes)
    if len(salt) != sha256.New().Size() {
        return "", "", nil
    }

    // Correct usage of PBKDF2 with HMAC and SHA256
    key := hmac.New(sha256.New, []byte(password))
    ok := key.SetMACKey([]byte(password))
    if !ok {
        return "", "", nil
    }

    // Compute the hash
    key.Sum(nil)

    // Encode the salt and hashed password in base64 for storage
    saltStr := base64.StdEncoding.EncodeToString(salt)
    hashStr := base64.StdEncoding.EncodeToString(key.Sum(nil))

    return saltStr, hashStr, nil
}
